package com.sponsormatch.controller;
import com.sponsormatch.dto.CollaborationDtos.*;import com.sponsormatch.entity.RequestStatus;import com.sponsormatch.service.CollaborationService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequiredArgsConstructor public class CollaborationController {private final CollaborationService service;@PostMapping("/api/shortlists")public ShortlistResponse shortlist(@AuthenticationPrincipal Long uid,@Valid @RequestBody ShortlistRequest r){return service.add(uid,r);}@GetMapping("/api/shortlists")public List<ShortlistResponse> shortlists(@AuthenticationPrincipal Long uid){return service.list(uid);}@DeleteMapping("/api/shortlists/{id}")public void remove(@AuthenticationPrincipal Long uid,@PathVariable Long id){service.remove(uid,id);}@PostMapping("/api/collaboration-requests")public CollaborationResponse send(@AuthenticationPrincipal Long uid,@Valid @RequestBody CollaborationRequestDto r){return service.send(uid,r);}@GetMapping("/api/collaboration-requests/sent")public List<CollaborationResponse> sent(@AuthenticationPrincipal Long uid){return service.sent(uid);}@GetMapping("/api/collaboration-requests/received")public List<CollaborationResponse> received(@AuthenticationPrincipal Long uid){return service.received(uid);}@PatchMapping("/api/collaboration-requests/{id}/accept")public CollaborationResponse accept(@AuthenticationPrincipal Long uid,@PathVariable Long id){return service.decide(uid,id,RequestStatus.ACCEPTED);}@PatchMapping("/api/collaboration-requests/{id}/reject")public CollaborationResponse reject(@AuthenticationPrincipal Long uid,@PathVariable Long id){return service.decide(uid,id,RequestStatus.REJECTED);}@GetMapping("/api/notifications")public List<NotificationResponse> notifications(@AuthenticationPrincipal Long uid){return service.notifications(uid);}@PatchMapping("/api/notifications/{id}/read")public NotificationResponse read(@AuthenticationPrincipal Long uid,@PathVariable Long id){return service.read(uid,id);}}
